    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the background as the most common value. Boundary runs are
    # launch bars; interior non-background cells are the ray targets.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    edge_colors = {
        grid[r][c]
        for r in range(h) for c in range(w)
        if (r == 0 or r == h - 1 or c == 0 or c == w - 1)
        and grid[r][c] != bg
    }
    targets = {
        grid[r][c]
        for r in range(1, h - 1) for c in range(1, w - 1)
        if grid[r][c] != bg and grid[r][c] not in edge_colors
    }
    if not targets:
        return out

    target = next(iter(targets))

    def project(start_r, start_c, dr, dc):
        r, c = start_r + dr, start_c + dc
        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] == target:
                out[r][c] = 4
                break
            if grid[r][c] != bg:
                break
            out[r][c] = target
            r += dr
            c += dc

    # Each non-background edge cell in a contiguous bar launches inward.
    for c in range(w):
        if grid[0][c] != bg:
            project(0, c, 1, 0)
        if grid[h - 1][c] != bg:
            project(h - 1, c, -1, 0)
    for r in range(h):
        if grid[r][0] != bg:
            project(r, 0, 0, 1)
        if grid[r][w - 1] != bg:
            project(r, w - 1, 0, -1)

    return out
